sealed class RenameRoot : XmlSyntaxRewriter
{
    public override XmlSyntaxNode? VisitElement(XmlElementSyntax node)
        => node.Name == "root" ? node.WithName("renamed") : base.VisitElement(node);
}

sealed class Counter : XmlSyntaxVisitor
{
    public int Count { get; private set; }
    public override void VisitElement(XmlElementSyntax node) => Count++;
}

sealed class ElementNameVisitor : XmlSyntaxVisitor<string?>
{
    public override string? VisitElement(XmlElementSyntax node) => node.Name;
}
